                { id: "q10", cat: "s9", q: "Dans 'de belles robes de soie', quel mot est un adjectif qualificatif ?", opts: ["A) belles", "B) robes", "C) soie"], ans: 0, exp: "'belles' est l'adjectif qualificatif épithète du nom 'robes'." }
