        let activeTextData = fullTextData;
        let activeSource = '1883';
        let currentSentenceIdx = 0;
        let isPlaying = false;
        let speechSynth = window.speechSynthesis;
        let currentUtterance = null;
        let allSentencesList = [];
        let userQuizAnswers = {};

        // INITIALIZATION ON LOAD
        window.onload = function() {
            renderInteractiveText();
            renderLexicalExercise();
            switchTab('summary'); // Default tab set to 'summary' as requested
        };

        // TAB SWITCHING FUNCTION
        function switchTab(tabId) {
            document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));
            const activeContent = document.getElementById('tab-' + tabId);
            if (activeContent) activeContent.classList.remove('hidden');

            document.querySelectorAll('.tab-btn').forEach(btn => {
                btn.classList.remove('bg-amber-600', 'text-white', 'shadow-md');
                btn.classList.add('text-slate-300', 'hover:text-white', 'hover:bg-slate-800');
            });

            const activeBtn = document.getElementById('tab-btn-' + tabId);
            if (activeBtn) {
                activeBtn.classList.remove('text-slate-300', 'hover:text-white', 'hover:bg-slate-800');
                activeBtn.classList.add('bg-amber-600', 'text-white', 'shadow-md');
            }

            if (tabId === 'exercises') {
                showQuizSection('all');
            }

            if (tabId !== 'reader') {
                stopAudio();
            }
        }

        function switchSource(source) {
            stopAudio();
            activeSource = source;
            activeTextData = source === '1806' ? pronote1806TextData : fullTextData;
            const label = document.getElementById('source-label');
            const description = document.getElementById('source-description');
            const btn1883 = document.getElementById('source-btn-1883');
            const btn1806 = document.getElementById('source-btn-1806');
            const is1883 = source === '1883';
            if (label) label.innerText = is1883 ? 'Wikisource 1883' : 'PDF Pronote — Barba 1806';
            if (description) description.innerText = is1883
                ? 'Version Wikisource 1883 : édition à rechercher comme indiqué dans la consigne de Pronote.'
                : 'Version du PDF transmis dans Pronote : Contes moraux pour l’instruction de la jeunesse, Barba, 1806.';
            [btn1883, btn1806].forEach(btn => {
                if (!btn) return;
                btn.className = 'px-3 py-1.5 rounded-lg text-xs font-bold transition ' + (btn === (is1883 ? btn1883 : btn1806)
                    ? 'bg-amber-600 text-white shadow-sm'
                    : 'bg-slate-100 text-slate-700 hover:bg-slate-200');
            });
            renderInteractiveText();
        }

        // RENDER THE SELECTED EDITION
        function renderInteractiveText() {
            const container = document.getElementById('text-container');
            if (!container) return;
            container.innerHTML = '';
            allSentencesList = [];

            activeTextData.forEach(chap => {
                const chapHeading = document.createElement('h2');
                chapHeading.className = 'font-serif text-xl sm:text-2xl font-bold text-amber-900 border-b-2 border-amber-300 pb-2 mt-4 mb-4';
                chapHeading.innerText = chap.chapterTitle;
                container.appendChild(chapHeading);

                chap.paragraphs.forEach(paragraph => {
                    const pElem = document.createElement('p');
                    pElem.className = 'mb-4 leading-relaxed';

                    paragraph.forEach(item => {
                        const span = document.createElement('span');
                        span.innerText = item.text + ' ';
                        span.className = 'sentence-clickable';
                        span.id = 'sentence-' + item.id;
                        span.onclick = () => playSingleSentence(item.id);

                        pElem.appendChild(span);
                        allSentencesList.push(item);
                    });

                    container.appendChild(pElem);
                });
            });
        }

        // AUDIO FUNCTIONS
        function playSingleSentence(id) {
            stopAudio();
            const sObj = allSentencesList.find(s => s.id === id);
            if (!sObj) return;

            highlightSentence(id);
            speakText(sObj.text, () => {
                clearHighlights();
            });
        }

        function togglePlayAll() {
            if (isPlaying) {
                stopAudio();
            } else {
                isPlaying = true;
                const icon = document.getElementById('play-icon');
                const txt = document.getElementById('play-text');
                if (icon) icon.innerText = '⏸️';
                if (txt) txt.innerText = 'Pause';
                playNextInSequence(currentSentenceIdx);
            }
        }

        function playNextInSequence(index) {
            if (!isPlaying || index >= allSentencesList.length) {
                stopAudio();
                return;
            }

            currentSentenceIdx = index;
            const sObj = allSentencesList[index];
            highlightSentence(sObj.id);

            speakText(sObj.text, () => {
                if (isPlaying) {
                    playNextInSequence(index + 1);
                }
            });
        }

        function speakText(text, onEndCallback) {
            if (!speechSynth) return;

            speechSynth.cancel();
            currentUtterance = new SpeechSynthesisUtterance(text);
            currentUtterance.lang = 'fr-FR';

            const rateSelect = document.getElementById('rate-select');
            const rate = rateSelect ? parseFloat(rateSelect.value) : 1.0;
            currentUtterance.rate = rate;

            currentUtterance.onend = function() {
                if (onEndCallback) onEndCallback();
            };

            currentUtterance.onerror = function() {
                if (onEndCallback) onEndCallback();
            };

            speechSynth.speak(currentUtterance);
        }

        function stopAudio() {
            isPlaying = false;
            if (speechSynth) speechSynth.cancel();
            const icon = document.getElementById('play-icon');
            const txt = document.getElementById('play-text');
            if (icon) icon.innerText = '▶️';
            if (txt) txt.innerText = 'Lecture Vocale';
            clearHighlights();
        }

        function highlightSentence(id) {
            clearHighlights();
            const elem = document.getElementById('sentence-' + id);
            if (elem) {
                elem.classList.add('sentence-active');
                elem.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }

        function clearHighlights() {
            document.querySelectorAll('.sentence-active').forEach(el => el.classList.remove('sentence-active'));
        }


        const fearWordsData = [
            { text: "horrible", target: true }, { text: "s’évanouir", target: true }, { text: "voix terrible", target: true },
            { text: "tremblant", target: true }, { text: "frayeur", target: true }, { text: "sifflement épouvantable", target: true },
            { text: "rose", target: false }, { text: "château", target: false }, { text: "déjeuner", target: false }, { text: "marchand", target: false }
        ];
        const angerWordsData = [
            { text: "ingrat", target: true }, { text: "faute", target: true }, { text: "mourir", target: true }, { text: "furie", target: true },
            { text: "menace", target: true }, { text: "terrible", target: true }, { text: "pardonner", target: false }, { text: "rose", target: false },
            { text: "chocolat", target: false }, { text: "bonté", target: false }
        ];

        // WORD-CLASSIFICATION EXERCISES : S2 PEUR / COLÈRE
        function renderWordExercise(kind, data, boxId, countId, feedbackId) {
            const container = document.getElementById(boxId);
            if (!container) return;
            container.innerHTML = '';
            data.forEach((item, idx) => {
                const span = document.createElement('button');
                span.type = 'button';
                span.className = 'cursor-pointer hover:bg-white px-2 py-1 rounded-lg transition inline-block m-1 border border-transparent font-serif text-left';
                span.innerText = item.text;
                span.onclick = () => toggleWord(kind, idx, span);
                container.appendChild(span);
            });
            updateWordCount(kind, data, countId, feedbackId);
        }
        function toggleWord(kind, idx, element) {
            const data = kind === 'fear' ? fearWordsData : angerWordsData;
            const color = kind === 'fear' ? ['bg-emerald-500','border-emerald-600'] : ['bg-orange-500','border-orange-600'];
            if (element.dataset.selected === 'true') {
                element.dataset.selected = 'false';
                element.classList.remove('text-white', color[0], color[1], 'bg-rose-500', 'border-rose-600');
                element.classList.add('hover:bg-white');
                data[idx].selected = false;
            } else {
                element.dataset.selected = 'true';
                element.classList.remove('hover:bg-white');
                if (data[idx].target) element.classList.add(...color, 'text-white');
                else element.classList.add('bg-rose-500', 'border-rose-600', 'text-white');
                data[idx].selected = true;
            }
            updateWordCount(kind, data, kind === 'fear' ? 'fear-count' : 'anger-count', kind === 'fear' ? 'fear-feedback' : 'anger-feedback');
        }
        function updateWordCount(kind, data, countId, feedbackId) {
            const found = data.filter(d => d.target && d.selected).length;
            const wrong = data.filter(d => !d.target && d.selected).length;
            const total = data.filter(d => d.target).length;
            const count = document.getElementById(countId); if (count) count.innerText = `${found} / ${total}`;
            const feedback = document.getElementById(feedbackId); if (!feedback) return;
            if (found === total && wrong === 0) { feedback.className = 'text-xs font-bold text-emerald-600'; feedback.innerText = '🎉 Bravo, tout est juste !'; }
            else if (wrong) { feedback.className = 'text-xs font-semibold text-rose-600'; feedback.innerText = 'Oups ! Un ou plusieurs mots ne correspondent pas.'; }
            else { feedback.className = kind === 'fear' ? 'text-xs font-semibold text-rose-700' : 'text-xs font-semibold text-orange-700'; feedback.innerText = kind === 'fear' ? 'À toi de trouver les indices de peur.' : 'À toi de repérer les mots de la colère.'; }
        }
        function renderLexicalExercise() {
            renderWordExercise('fear', fearWordsData, 'fear-word-box', 'fear-count', 'fear-feedback');
            renderWordExercise('anger', angerWordsData, 'anger-word-box', 'anger-count', 'anger-feedback');
        }
        function resetWordExercise(kind) {
            const data = kind === 'fear' ? fearWordsData : angerWordsData;
            data.forEach(d => d.selected = false);
            renderLexicalExercise();
        }

        // QUIZ LOGIC FOR ALL 10 QUESTIONS
        function showQuizSection(filterKey) {
            ['all', 's2', 's4', 's6', 's9'].forEach(k => {
                const btn = document.getElementById('qtab-' + k);
                if (btn) {
                    if (k === filterKey) {
                        btn.className = 'px-3 py-1.5 rounded-lg text-xs font-bold bg-amber-600 text-white shadow-sm';
                    } else {
                        btn.className = 'px-3 py-1.5 rounded-lg text-xs font-bold bg-slate-100 text-slate-700 hover:bg-slate-200';
                    }
                }
            });

            let questionsToDisplay = [];
            if (filterKey === 'all') {
                Object.keys(quizDatabase).forEach(cat => {
                    questionsToDisplay = questionsToDisplay.concat(quizDatabase[cat]);
                });
            } else if (quizDatabase[filterKey]) {
                questionsToDisplay = quizDatabase[filterKey];
            }

            const container = document.getElementById('quiz-questions-container');
            if (!container) return;
            container.innerHTML = '';

            questionsToDisplay.forEach((qObj, globalIdx) => {
                const qCard = document.createElement('div');
                qCard.className = 'p-4 rounded-xl border border-slate-200 bg-slate-50 space-y-3 shadow-sm';
                
                const title = document.createElement('h4');
                title.className = 'font-bold text-slate-800 text-sm sm:text-base flex items-start space-x-2';
                title.innerHTML = `<span class="bg-amber-200 text-amber-900 text-xs px-2.5 py-0.5 rounded-full font-bold uppercase">${qObj.cat.toUpperCase()} - Q${globalIdx + 1}</span> <span>${qObj.q}</span>`;
                qCard.appendChild(title);

                const optsGrid = document.createElement('div');
                optsGrid.className = 'grid grid-cols-1 sm:grid-cols-3 gap-2';

                qObj.opts.forEach((optText, optIdx) => {
                    const btn = document.createElement('button');
                    btn.className = 'p-2.5 border rounded-lg text-xs text-left font-medium transition bg-white hover:bg-amber-50';
                    btn.innerText = optText;
                    
                    const answerKey = qObj.id;
                    if (userQuizAnswers[answerKey] !== undefined) {
                        if (optIdx === qObj.ans) {
                            btn.classList.add('bg-emerald-100', 'border-emerald-500', 'text-emerald-900', 'font-bold');
                        } else if (userQuizAnswers[answerKey] === optIdx) {
                            btn.classList.add('bg-rose-100', 'border-rose-500', 'text-rose-900');
                        }
                    }

                    btn.onclick = () => handleQuizAnswer(qObj.id, optIdx, filterKey);
                    optsGrid.appendChild(btn);
                });

                qCard.appendChild(optsGrid);

                const expBox = document.createElement('div');
                const answerKey = qObj.id;
                if (userQuizAnswers[answerKey] !== undefined) {
                    expBox.className = 'text-xs p-3 rounded-lg font-medium ' + (userQuizAnswers[answerKey] === qObj.ans ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800');
                    expBox.innerHTML = (userQuizAnswers[answerKey] === qObj.ans ? '✅ Excellente réponse ! ' : '❌ Explication : ') + qObj.exp;
                } else {
                    expBox.className = 'hidden text-xs p-3 rounded-lg font-medium';
                }
                qCard.appendChild(expBox);

                container.appendChild(qCard);
            });

            updateOverallQuizScore();
        }

        function handleQuizAnswer(questionId, selectedOptIdx, currentFilter) {
            userQuizAnswers[questionId] = selectedOptIdx;
            showQuizSection(currentFilter);
        }

        function updateOverallQuizScore() {
            let totalAnswered = 0;
            let totalCorrect = 0;
            
            let allQuestions = [];
            Object.keys(quizDatabase).forEach(cat => {
                allQuestions = allQuestions.concat(quizDatabase[cat]);
            });

            allQuestions.forEach(qObj => {
                if (userQuizAnswers[qObj.id] !== undefined) {
                    totalAnswered++;
                    if (userQuizAnswers[qObj.id] === qObj.ans) {
                        totalCorrect++;
                    }
                }
            });

            const scoreDisplay = document.getElementById('quiz-score-display');
            if (scoreDisplay) scoreDisplay.innerText = `${totalCorrect} / ${allQuestions.length}`;
        }
